@Component("creditor-handler")
@ProcessingGroup("creditor-processing-group")
public class CreditorEventHandler {
	
	// core constructor
	CreditorEventHandler(EntityManager entityManager) {
        this.entityManager = entityManager;
    }	
	
    /*
     * @param	event CreateCreditorEvent
     */
    @EventHandler
    public void handle( CreateCreditorEvent event) {
        entityManager.persist(new Creditor(event.getCreditorId(), event.getName(), event.getBic(), event.getAddress(), event.getMandates()));
    }

    /*
     * @param	event UpdateCreditorEvent
     */
    @EventHandler
    public Creditor handle( UpdateCreditorEvent event) {
    	entityManager.merge(new Creditor(event.getCreditorId(), event.getName(), event.getBic(), event.getAddress(), event.getMandates()));
    }
    
    /*
     * @param	event DeleteCreditorEvent
     */
    @EventHandler
    public void on( DeleteCreditorEvent event) {
    	Creditor entity = new Creditor();
   
    	// ------------------------------------------
    	// apply the CreditorId
    	// ------------------------------------------
    	entity.setCreditorId( event.getCreditorId() );
    	
    	// ------------------------------------------
    	// add to an Iterable and delete
    	// ------------------------------------------
    	entityManager.remove( entity );
    }    
    
    // attributes
	private final CreditorRepository creditorEntityRepository;
    private static final Logger LOGGER 			= Logger.getLogger(CreditorEventHandler.class.getName());

}
